SET local check_function_bodies = off;

CREATE TABLE "public"."arqueros" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre"           character varying(150)   NOT NULL,
  "identificacion"   character varying(30)    NOT NULL,
  "fecha_nacimiento" date,
  "telefono"         character varying(30),
  "correo"           character varying(255),
  "mano_dominante"   character varying(20),
  "tipo_arco_id"     bigint,
  "categoria"        character varying(100),
  "afiliacion"       character varying(100),
  "club_id"          bigint,
  "observaciones"    text,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "arqueros_identificacion_unique" UNIQUE (identificacion),
  CONSTRAINT "arqueros_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."arqueros"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."asignaciones_piezas" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "arquero_id"       bigint                   NOT NULL,
  "pieza_id"         bigint                   NOT NULL,
  "cantidad"         integer                  NOT NULL DEFAULT 1,
  "fecha_asignacion" timestamp with time zone NOT NULL DEFAULT now(),
  "fecha_devolucion" timestamp with time zone,
  "estado"           character varying(30)    NOT NULL DEFAULT 'activo'::character varying,
  "observaciones"    text,
  "registrado_por"   uuid,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "asignaciones_piezas_cantidad_check" CHECK ((cantidad > 0)),
  CONSTRAINT "asignaciones_piezas_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."asignaciones_piezas"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."asignaciones" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "arquero_id"       bigint                   NOT NULL,
  "inventario_id"    bigint                   NOT NULL,
  "cantidad"         integer                  NOT NULL DEFAULT 1,
  "fecha_asignacion" timestamp with time zone NOT NULL DEFAULT now(),
  "fecha_devolucion" timestamp with time zone,
  "estado"           character varying(30)    NOT NULL DEFAULT 'activo'::character varying,
  "observaciones"    text,
  "registrado_por"   uuid,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "asignaciones_cantidad_check" CHECK ((cantidad > 0)),
  CONSTRAINT "asignaciones_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."asignaciones"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."categorias" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre"      character varying(100)   NOT NULL,
  "descripcion" text,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "categorias_nombre_unique" UNIQUE (nombre),
  CONSTRAINT "categorias_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."categorias"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."clubes" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre"      character varying(150)   NOT NULL,
  "ubicacion"   character varying(250),
  "descripcion" text,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "clubes_nombre_unique" UNIQUE (nombre),
  CONSTRAINT "clubes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."clubes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."inventario" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre"              character varying(150)   NOT NULL,
  "codigo"              character varying(50),
  "tipo"                character varying(100)   NOT NULL,
  "descripcion"         text,
  "cantidad"            integer                  NOT NULL DEFAULT 1,
  "cantidad_disponible" integer                  NOT NULL DEFAULT 1,
  "ubicacion"           character varying(150),
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "inventario_cantidad_check" CHECK ((cantidad >= 0)),
  CONSTRAINT "inventario_codigo_unique" UNIQUE (codigo),
  CONSTRAINT "inventario_disponible_check" CHECK (((cantidad_disponible >= 0) AND (cantidad_disponible <= cantidad))),
  CONSTRAINT "inventario_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."inventario"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."pagos" (
  "id"             bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "arquero_id"     bigint                   NOT NULL,
  "concepto"       character varying(150)   NOT NULL,
  "monto"          numeric(12,2)            NOT NULL,
  "fecha_pago"     date                     NOT NULL DEFAULT CURRENT_DATE,
  "periodo"        character varying(50),
  "metodo_pago"    character varying(50),
  "referencia"     character varying(100),
  "observaciones"  text,
  "registrado_por" uuid,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "pagos_monto_check" CHECK ((monto >= (0)::numeric)),
  CONSTRAINT "pagos_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."pagos"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."perfiles" (
  "id"         uuid                     NOT NULL,
  "nombre"     character varying(150)   NOT NULL,
  "correo"     character varying(255),
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "perfiles_correo_unique" UNIQUE (correo),
  CONSTRAINT "perfiles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."perfiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."piezas" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre"              character varying(150)   NOT NULL,
  "tipo"                character varying(100),
  "descripcion"         text,
  "cantidad"            integer                  NOT NULL DEFAULT 0,
  "cantidad_disponible" integer                  NOT NULL DEFAULT 0,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "piezas_cantidad_check" CHECK ((cantidad >= 0)),
  CONSTRAINT "piezas_disponible_check" CHECK (((cantidad_disponible >= 0) AND (cantidad_disponible <= cantidad))),
  CONSTRAINT "piezas_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."piezas"
